نقش سازمانی: inventory_planning_manager (inventory_planning_manager)

درخواست کاربر:
«نان و نیم‌فروشی» و «سرمودی و فریزری» را از نظر سرمایه در گردش مقایسه کن. (مدیر موجودی — مارکت دی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "stock_levels",
      "description": "موجودی به تفکیک دستهٔ کالا و شعبه",
      "dimensions": [
        "category",
        "branch"
      ],
      "measures": [
        "stock_m",
        "daily_sales_m"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "days_cover",
      "description": "پوشش موجودی",
      "formula": "موجودی تقسیم بر فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "category"
      ]
    },
    {
      "metric": "stock_turnover",
      "description": "گردش موجودی",
      "formula": "فروش دوره تقسیم بر میانگین موجودی",
      "unit": "بار",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "سفارش‌گذاری روزانه از مرکز توزیع",
    "انقضا با آستانهٔ هشدار سی روز پایش می‌شود",
    "سقف پوشش موجودی دسته‌های فاسدشدنی هفت روز"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "stock_levels",
    "filters": {
      "category": [
        "نان و نیم‌فروشی",
        "سرمودی و فریزری"
      ],
      "period": "today"
    }
  }
}

TOOL_OBSERVATION:
{
  "نان و نیم‌فروشی": {
    "days_cover": 25,
    "daily_sales_m": 105,
    "stock_m": 2625,
    "turnover": 1.2,
    "margin_pct": 25.4
  },
  "سرمودی و فریزری": {
    "days_cover": 15,
    "daily_sales_m": 240,
    "stock_m": 3600,
    "turnover": 2.0,
    "margin_pct": 20.5
  }
}

نقش سازمانی: inventory_planning_manager (inventory_planning_manager)

درخواست کاربر:
آماده‌سازی انبار برای پیک؛ عدد بده. (زنجیرهٔ شهروند)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "demand_forecast",
      "description": "پیش‌بینی و فروش واقعی هر دسته و هفته",
      "dimensions": [
        "category",
        "week"
      ],
      "measures": [
        "forecast_units",
        "actual_units"
      ]
    },
    {
      "dataset": "po_pending",
      "description": "سفارش‌های باز در راه",
      "dimensions": [
        "supplier",
        "category"
      ],
      "measures": [
        "qty_ton",
        "eta_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "days_cover",
      "description": "پوشش موجودی",
      "formula": "موجودی تقسیم بر فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "category"
      ]
    },
    {
      "metric": "forecast_accuracy",
      "description": "دقت پیش‌بینی تقاضا",
      "formula": "یک منهای قدرمطلق خطا تقسیم بر واقعی",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "کمپین‌های تخفیف ماهانه بر تقاضا اثر می‌گذارد",
    "سفارش‌گذاری روزانه از مرکز توزیع",
    "سیستم پیش‌بینی تقاضا برای دسته‌های اصلی فعال است"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "demand_forecast",
    "filters": {
      "category": "تنقلات و شکلات",
      "period": "last_year_peak"
    }
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "po_pending",
    "filters": {
      "category": "تنقلات و شکلات",
      "period": "next_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "open_orders_ton": 800,
  "note": "ظرفیت تحویل تأمین‌کنندگان در پیک ثبت نشده"
}

نقش سازمانی: inventory_planning_manager (inventory_planning_manager)

درخواست کاربر:
ناهنجاری انقضا در «کنسرو و غذای آماده» را باز کن. (زنجیرهٔ شهروند)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "expiry_report",
      "description": "ارزش کالای نزدیک انقضا",
      "dimensions": [
        "category",
        "branch"
      ],
      "measures": [
        "exp_value_m",
        "exp_days"
      ]
    },
    {
      "dataset": "stock_levels",
      "description": "موجودی به تفکیک دستهٔ کالا و شعبه",
      "dimensions": [
        "category",
        "branch"
      ],
      "measures": [
        "stock_m",
        "daily_sales_m"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "expiry_rate",
      "description": "نرخ کالای نزدیک انقضا",
      "formula": "ارزش نزدیک انقضا تقسیم بر موجودی کل",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "سقف پوشش موجودی دسته‌های فاسدشدنی هفت روز",
    "سیستم پیش‌بینی تقاضا برای دسته‌های اصلی فعال است",
    "سفارش‌گذاری روزانه از مرکز توزیع"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "expiry_rate"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ]
  }
}

TOOL_OBSERVATION:
{
  "expiry_rate_pct": {
    "prev": 2.1,
    "curr": 8.1,
    "change_pp": 6.0
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "expiry_report",
    "filters": {
      "category": "کنسرو و غذای آماده",
      "period": "curr_month"
    }
  }
}

